```python
from decimal import Decimal
x,y,z = map(Decimal, input().split())
res = [y**z * x.ln(), z**y * x.ln(), y*z * x.ln(), y*z * x.ln(), x**z * y.ln(), z**x * y.ln(), x*z * y.ln(), x*z * y.ln(), x**y * z.ln(), y**x * z.ln(), x*y * z.ln(), x*y * z.ln()]
arr = ['x^y^z','x^z^y','(x^y)^z','(x^z)^y', 'y^x^z','y^z^x','(y^x)^z','(y^z)^x', 'z^x^y','z^y^x','(z^x)^y','(z^y)^x']
print(arr[res.index(max(res))])
```

